-- Explicit references from celebration experience items to canonical shared vendors.
begin;
create table if not exists public.cb_experience_vendor_links(item_id uuid primary key references public.cb_experience_items on delete cascade,vendor_id uuid references public.cb_shared_vendors on delete set null,vendor_revision bigint,revision bigint not null default 1,updated_at timestamptz not null default now());
create table if not exists public.cb_experience_vendor_writes(user_id uuid not null references auth.users on delete cascade,client uuid not null,payload jsonb not null,response jsonb not null,primary key(user_id,client));
create table if not exists public.cb_experience_vendor_history(item_id uuid not null references public.cb_experience_items on delete cascade,revision bigint not null,actor_id uuid not null references auth.users,snapshot jsonb not null,at timestamptz not null default now(),primary key(item_id,revision));
alter table public.cb_experience_vendor_links enable row level security;alter table public.cb_experience_vendor_writes enable row level security;alter table public.cb_experience_vendor_history enable row level security;
revoke all on public.cb_experience_vendor_links,public.cb_experience_vendor_writes,public.cb_experience_vendor_history from public,anon,authenticated;
create or replace function public.cb_experience_vendor_context(p_item uuid,p_search text default '') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare i public.cb_experience_items;e public.cb_project_events;l public.cb_experience_vendor_links;v public.cb_shared_vendors;begin
 select * into i from public.cb_experience_items where id=p_item;select * into e from public.cb_project_events where id=i.event_id;
 if i.id is null or not coalesce(public.cb_project_access(e.project_id,'write') and public.cb_experience_member(e.id,auth.uid()),false) then raise exception 'Celebration planning access required' using errcode='42501';end if;
 if p_search is null or length(p_search)>100 then raise exception 'Search using up to 100 characters';end if;
 select * into l from public.cb_experience_vendor_links where item_id=i.id;
 select * into v from public.cb_shared_vendors where id=l.vendor_id and project_id=e.project_id and public.cb_shared_vendor_access(id);
 return jsonb_build_object('item',i.id,'item_revision',i.revision,'event',e.id,'event_revision',e.revision,'project',e.project_id,'title',i.data->>'title','cancelled',i.data->>'status'='Cancelled','revision',coalesce(l.revision,0),'vendor',case when v.id is null then null else jsonb_build_object('id',v.id,'name',v.name,'category',v.details->>'category','revision',v.revision,'archived',v.archived,'changed',l.vendor_revision is distinct from v.revision) end,'choices',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'category',x.details->>'category','revision',x.revision) order by x.name,x.id),'[]') from (select * from public.cb_shared_vendors where project_id=e.project_id and not archived and public.cb_shared_vendor_access(id) and strpos(lower(name||' '||coalesce(details->>'category','')),lower(p_search))>0 order by name,id limit 50) x));end;$$;
create or replace function public.cb_save_experience_vendor(p_item uuid,p_item_revision bigint,p_event_revision bigint,p_revision bigint,p_client uuid,p_vendor uuid,p_vendor_revision bigint,p_confirm boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare i public.cb_experience_items;e public.cb_project_events;l public.cb_experience_vendor_links;v public.cb_shared_vendors;w public.cb_experience_vendor_writes;payload jsonb;result jsonb;begin
 select * into i from public.cb_experience_items where id=p_item;select * into e from public.cb_project_events where id=i.event_id;perform 1 from public.cb_projects where id=e.project_id for update;select * into e from public.cb_project_events where id=i.event_id for update;
 if i.id is null or not coalesce(public.cb_project_access(e.project_id,'write') and public.cb_experience_member(e.id,auth.uid()),false) then raise exception 'Celebration planning access required' using errcode='42501';end if;
 payload=jsonb_build_object('item',p_item,'item_revision',p_item_revision,'event_revision',p_event_revision,'revision',p_revision,'vendor',p_vendor,'vendor_revision',p_vendor_revision,'confirm',p_confirm);
 if p_client is null then raise exception 'Request ID required';end if;select * into w from public.cb_experience_vendor_writes where user_id=auth.uid() and client=p_client;if found then if w.payload is distinct from payload then raise exception 'Retry the original professional connection' using errcode='PT409';end if;return w.response;end if;
 if p_confirm is distinct from true then raise exception 'Review and confirm this professional connection';end if;
 select * into i from public.cb_experience_items where id=p_item for update;if i.data->>'status'='Cancelled' then raise exception 'Reopen the cancelled experience before changing its professional';end if;
 if i.revision is distinct from p_item_revision or e.revision is distinct from p_event_revision then raise exception 'The celebration or service changed. Refresh before connecting a professional.' using errcode='PT409';end if;
 if p_vendor is not null then select * into v from public.cb_shared_vendors where id=p_vendor and project_id=e.project_id and not archived and public.cb_shared_vendor_access(id) for update;if v.id is null then raise exception 'Choose an active professional in this wedding' using errcode='42501';end if;if v.revision is distinct from p_vendor_revision then raise exception 'The professional record changed. Refresh before confirming.' using errcode='PT409';end if;
 elsif p_vendor_revision is not null then raise exception 'Clear the professional revision when removing a connection';end if;
 select * into l from public.cb_experience_vendor_links where item_id=p_item for update;if coalesce(l.revision,0) is distinct from p_revision then raise exception 'Another teammate changed this connection. Refresh first.' using errcode='PT409';end if;
 insert into public.cb_experience_vendor_links(item_id,vendor_id,vendor_revision) values(p_item,p_vendor,p_vendor_revision) on conflict(item_id) do update set vendor_id=excluded.vendor_id,vendor_revision=excluded.vendor_revision,revision=public.cb_experience_vendor_links.revision+1,updated_at=now() returning * into l;
 insert into public.cb_experience_vendor_history values(l.item_id,l.revision,auth.uid(),to_jsonb(l),now());result=jsonb_build_object('saved',true,'revision',l.revision);insert into public.cb_experience_vendor_writes values(auth.uid(),p_client,payload,result);return result;end;$$;
revoke all on function public.cb_experience_vendor_context(uuid,text),public.cb_save_experience_vendor(uuid,bigint,bigint,bigint,uuid,uuid,bigint,boolean) from public,anon,authenticated;
grant execute on function public.cb_experience_vendor_context(uuid,text),public.cb_save_experience_vendor(uuid,bigint,bigint,bigint,uuid,uuid,bigint,boolean) to authenticated;
notify pgrst,'reload schema';commit;
